const hoy = new Date().toISOString().slice(0, 10);
// Google Sheets acepta hasta 50.000 caracteres por celda.
const celda = s => (s && s.length > 45000 ? s.slice(0, 45000) + ' [cortado]' : s);
const r = leer($json);
const cfg = $('Config').first().json;
return [{ json: { fecha: hoy, cliente: cfg.cliente, oferta: r.oferta || cfg.oferta,
  horas_totales: r.horas_totales, entrega_dia_desde_la_firma: r.entrega_dia_desde_la_firma,
  tareas: celda((r.tareas || []).map(t => 'Día ' + t.dia_desde_la_firma + ': ' + t.tarea + ' (' + t.quien + ', ' + t.horas + ' h)').join('\n')),
  pedir_al_comercio: celda((r.pedir_al_comercio || []).map(p => p.que + ' (para el día ' + p.para_cuando + '): ' + p.como).join('\n')),
  pruebas_antes_de_entregar: celda((r.pruebas_antes_de_entregar || []).join('\n')),
  falta_antes_de_empezar: celda((r.falta_antes_de_empezar || []).join('\n')),
  detalle: celda(JSON.stringify(r)) } }];
